// Android WebView client; host owns simulator/transport and durable workspace.
let bootstrap,session=null,queue=Promise.resolve(),desiredForeground=!document.hidden,heartbeatPending=false;const instance=new URL(location.href).searchParams.get('instance')??('browser-'+crypto.randomUUID());const android=new URL(location.href).searchParams.get('android')==='field02';
const cfg=()=>bootstrap??=fetch('/api/bootstrap').then(r=>r.json());
async function requestLife(action){const b=await cfg();const q={action,instance,platform:android?'ANDROID_WEBVIEW':'HOST_BROWSER',...session&&{clientId:session.id,clientEpoch:session.epoch,clientInstance:instance}};const r=await fetch('/api/client-session',{method:'POST',headers:{'Content-Type':'application/json','X-Field-CSRF':b.csrf},body:JSON.stringify(q)}),v=await r.json();if(!v.ok)throw Error(v.error);session=v.result;return session;}
function enqueue(fn){const result=queue.then(fn);queue=result.catch(()=>{});return result;}
window.field02Lifecycle=event=>{desiredForeground=event==='foreground';const wanted=event;return enqueue(async()=>{try{if(wanted==='foreground'){if(!desiredForeground)return;if(!session?.active)await requestLife('activate');if(!desiredForeground&&session?.active)await requestLife('background');}else if(session){await requestLife(wanted==='stop'?'stop':'background');}}catch(e){session=null;window.dispatchEvent(new Event('field02AuthorityLost'));}});};
window.field02ClientContext=()=>{if(!desiredForeground||!session?.active)throw Error('Cần đưa ứng dụng về foreground và cấp quyền mới');return{clientId:session.id,clientEpoch:session.epoch,clientInstance:instance};};
window.fieldBootstrap01=async()=>{const b=await cfg();await window.field02Lifecycle(document.hidden?'background':'foreground');return b;};
window.Native82Bridge={environment86:()=>JSON.stringify({source:'mock',hardware:android?'FIELD02_ANDROID_WEBVIEW_HOST_COMPANION':'FIELD02_HOST_NOT_ANDROID',sdk:null,webview:android?'ANDROID_WEBVIEW':'HOST_BROWSER',hasHostToken:false}),reportUI86:()=>{},request:(id,action,expected,body)=>cfg().then(b=>fetch('/api/native82',{method:'POST',headers:{'Content-Type':'application/json','X-Field-CSRF':b.csrf},body:JSON.stringify({action,expected,body})})).then(r=>r.json()).then(r=>window.native82Result(id,JSON.stringify(r.result??r))).catch(e=>window.native82Result(id,JSON.stringify({ok:false,error:e.message})))};
setInterval(()=>{if(heartbeatPending||!desiredForeground||!session?.active||document.hidden)return;heartbeatPending=true;enqueue(async()=>{if(!desiredForeground||!session?.active)return;try{await requestLife('heartbeat');if(!desiredForeground&&session?.active)await requestLife('background');}catch{session=null;window.dispatchEvent(new Event('field02AuthorityLost'));}}).finally(()=>heartbeatPending=false);},750);
document.addEventListener('visibilitychange',()=>window.field02Lifecycle(document.hidden?'background':'foreground'));window.addEventListener('pagehide',()=>window.field02Lifecycle('stop'));
for(const name of ['error','unhandledrejection'])window.addEventListener(name,()=>{if(document.body?.dataset.fieldLoading==='true')document.body.dataset.fieldMessage='Không thể nạp workspace. Tải lại để kiểm tra nguồn dữ liệu.';});
